import{_ as i,a0 as p,w as a,s as n,I as s,x as e,a1 as o,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"机器人学影响 CIO 角色的 3 种方式 | LCTT x X-CMD","titleTemplate":false,"description":"机器人学影响 CIO 角色的 3 种方式 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"机器人学影响 CIO 角色的 3 种方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"机器人学影响 CIO 角色的 3 种方式 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20171103 3 ways robotics affects the CIO role","title":"机器人学影响 CIO 角色的 3 种方式","tag":"201806","desc":""},"relativePath":"201806/20171103 3 ways robotics affects the CIO role.md","filePath":"[post].md"}'),f={name:"201806/20171103 3 ways robotics affects the CIO role.md"};function C(u,t,m,I,O,T){const r=p("Link");return a(),n("div",null,[t[19]||(t[19]=s("h1",{id:"机器人学影响-cio-角色的-3-种方式",tabindex:"-1"},[e("机器人学影响 CIO 角色的 3 种方式 "),s("a",{class:"header-anchor",href:"#机器人学影响-cio-角色的-3-种方式","aria-label":"Permalink to “机器人学影响 CIO 角色的 3 种方式”"},"​")],-1)),t[20]||(t[20]=s("blockquote",null,[s("p",null,"机器人流程自动化如何影响 CIO ？考虑这些可能。")],-1)),t[21]||(t[21]=s("p",null,[s("img",{src:"https://enterprisersproject.com/sites/default/files/styles/620x350/public/cio_ai.png?itok=toMIgELj",alt:"配图"})],-1)),t[22]||(t[22]=s("p",null,"随着 2017 的结束，许多 CIO 们的 2018 年目标也将确定。或许你们将参与到机器人流程自动化（RPA）中。多年以来，RPA 对许多公司来说只是一个可望不可及的概念。但是随着组织被迫变得越来越敏捷高效，RPA 所具有的潜在优势开始受到重视。",-1)),s("p",null,[t[1]||(t[1]=e("根据 Redwood Sofeware 和 Sapio Research 的最新 ",-1)),o(r,{href:"https://www.redwood.com/press-releases/it-decision-makers-speak-59-of-business-processes-could-be-automated-by-2022/"},{default:l(()=>[...t[0]||(t[0]=[e("研究报告",-1)])]),_:1}),t[2]||(t[2]=e("，IT 决策者们相信，未来 5 年有 59% 的业务可以被自动化处理，从而产生新的速度和效率，并且消减相应的重复性的人工工作量的岗位。但是，目前在相应岗位上没有实施 RPA 的公司中，有 20% 的公司员工超过 1000 人。",-1))]),t[23]||(t[23]=s("p",null,"对于 CIO 们来说，RPA 会潜在影响你在业务中的角色和你的团队。随着 RPA 的地位在 2018 年中越来越重要，CIO 们和其它 IT 决策者的角色也能会受到如下三种方式的改变：",-1)),t[24]||(t[24]=s("h3",{id:"成为战略性变革代理人的机会增加",tabindex:"-1"},[e("成为战略性变革代理人的机会增加 "),s("a",{class:"header-anchor",href:"#成为战略性变革代理人的机会增加","aria-label":"Permalink to “成为战略性变革代理人的机会增加”"},"​")],-1)),t[25]||(t[25]=s("p",null,"随着压力的增长，用最少的时间做更多的事，内部流程越来越重要。在每个企业中，员工们每天做着既重要又枯燥的一些任务。这些任务可能是枯燥且重复性的任务，但是要求他们必须快速完成且不能出错。",-1)),s("p",null,[s("strong",null,[t[4]||(t[4]=e("[有关你的自动化策略的 ROI 建议，查看我们相关的文章，",-1)),o(r,{href:"https://enterprisersproject.com/article/2017/11/how-improve-roi-automation-4-tips?sc_cid=70160000000h0aXAAQ"},{default:l(()=>[...t[3]||(t[3]=[e("如何在自动化方面提升 ROI：4 个小提示",-1)])]),_:1}),t[5]||(t[5]=e("。]",-1))])]),t[26]||(t[26]=d('<p>在财务中从后台的一些操作到采购、供应链、账务、客户服务、以及人力资源，在一个组织中几乎所有的岗位都有一些枯燥的任务。这就为 CIO 们提供了一个机会，将 IT 与业务联合起来，成为使用 RPA 进行战略变革的先锋。</p><p>除了过去的屏幕抓取技术，机器人现在已经实现可定制化，即插即用的解决方案可以根据企业的需要进行设计。使用这种以流程为中心的方法，企业不仅可以将以前由人来完成的任务进行自动化，也可以将应用程序和系统特定任务自动化，比如 ERP 和企业其它应用程序。</p><p>为端到端的流程实施更高级别的自动化将是 CIO 们的价值所在。CIO 们将会站在这种机遇的最前沿。</p><h3 id="重新关注人和培训" tabindex="-1">重新关注人和培训 <a class="header-anchor" href="#重新关注人和培训" aria-label="Permalink to “重新关注人和培训”">​</a></h3><p>技术的变动将让员工更加恐慌，尤其是当这些自动化的变动涉及到他们每日职责的相当大的部分。CIO 们应该清楚地告诉他们，RPA 将如何让他们的角色和责任变得更好，以及用数据说明的、最终将影响到他们底线的战略决策。</p><p>当实施 RPA 时，清晰明确地表达出“人对组织的成功来说是很重要的”信息是很关键的，并且，这种成功需要使技术和人的技能实现适当的平衡。</p><p>CIO 们也应该分析工作流并实施更好的流程，这种流程能够超越以前由终端用户完成的特定任务。通过端到端的流程自动化，CIO 们可以让员工表现更加出色。</p><p>因为在整个自动化的过程中，提升和培训员工技术是很重要的，CIO 们必须与企业高管们一起去决定，帮助员工自信地应对变化的培训项目。</p><h3 id="需要长远的规划" tabindex="-1">需要长远的规划 <a class="header-anchor" href="#需要长远的规划" aria-label="Permalink to “需要长远的规划”">​</a></h3><p>为确保机器人流程自动化的成功，甲方必须有一个长期的方法。这将要求一个弹性的解决方案，它将对整个业务模型有好处，包括消费者。比如，当年亚马逊为他的 Prime 消费者推广快速投递服务时，他们不仅在他们的仓库中重新调整了订单交付流程，他们也自动化了他们的在线客户体验，让它们变得更简化、更快速，并且让消费者比以前更容易下订单。</p><p>在即将到来的一年里，CIO 们可以用同样的方法来应用技术，构建整体的解决方案来改变组织的动作方式。裁员只会让最终效益产生很大影响，但是流程自动化将使 CIO 们能够通过优化和授权来考虑更大的问题。这种方法让 CIO 们去为他们自己和 RPA 构建长期的信誉。这反过来将强化 CIO 们作为探路者的角色，并为整个组织的成功作出贡献。</p><p>对于 CIO 们来说，采用一个长期的、策略性的方法让 RPA 成功，需要时间和艰苦的努力。尽管如此，那些致力于创建一种人力和技术平衡战略的 CIO 们，将会在现在和将来实现更大的价值。</p><hr>',13)),s("p",null,[t[7]||(t[7]=e("via: ",-1)),o(r,{href:"https://enterprisersproject.com/article/2017/11/3-ways-robotics-affects-cio-role"},{default:l(()=>[...t[6]||(t[6]=[e("https://enterprisersproject.com/article/2017/11/3-ways-robotics-affects-cio-role",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=e("作者：",-1)),o(r,{href:"https://enterprisersproject.com/user/dennis-walsh"},{default:l(()=>[...t[8]||(t[8]=[e("Dennis Walsh",-1)])]),_:1}),t[12]||(t[12]=e(" 译者：",-1)),o(r,{href:"https://github.com/qhwdw"},{default:l(()=>[...t[9]||(t[9]=[e("qhwdw",-1)])]),_:1}),t[13]||(t[13]=e(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:l(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创编译，",-1)),o(r,{href:"https://linux.cn/"},{default:l(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const x=i(f,[["render",C]]);export{P as __pageData,x as default};
